9	// listSessionsCmd resolves the projects root and lists it, all inside the Cmd:
10	// the model is not touched (Rule 110) and the answer carries gen back.
11	func listSessionsCmd(gen int) tea.Cmd {
12		return func() tea.Msg {
13			root, err := agentusage.ProjectsRoot()
14			if err != nil {
15				return sessionListLoadedMsg{gen: gen, err: err}
16			}
17			listing, err := agentusage.ListSessions(root)
18			return sessionListLoadedMsg{gen: gen, root: root, listing: listing, err: err}
19		}
20	}
21	
22	// parseSessionCmd locates and parses a session's transcripts, all inside the
23	// Cmd (Rule 110). parent is copied in by the caller; the answer carries gen.
24	func parseSessionCmd(gen int, parent string) tea.Cmd {
25		return func() tea.Msg {
26			files, err := agentusage.LocateSession(parent)
27			if err != nil {
28				return sessionUsageLoadedMsg{gen: gen, err: err}
29			}
30			usage, err := agentusage.ParseSession(files)
31			return sessionUsageLoadedMsg{gen: gen, usage: usage, err: err}
32		}
33	}
