1	package agentusageview
2	
3	import (
4		"fmt"
5		"sort"
6		"strings"
7	
8		"github.com/charmbracelet/lipgloss"
9	
10		"github.com/anthnel/devdesk/internal/agentusage"
11		"github.com/anthnel/devdesk/internal/ui/datatable"
12		"github.com/anthnel/devdesk/internal/ui/theme"
13	)
14	
15	const (
16		// noValue is the dash of a cell with nothing to show.
17		noValue = "-"
18		// noModel stands for an agent whose transcript named no model.
19		noModel = noValue
20		// unknownID stands for a sub-agent whose ID is empty, so it cannot be
21		// mistaken for the orchestrator, which has no short ID by design.
22		unknownID = "?"
23		// unknownType stands for a sub-agent whose meta file gave no type.
24		unknownType = "unknown"
25		// orchestratorLabel is the Agent cell of the main agent.
26		orchestratorLabel = "orchestrator"
27		// partialMark prefixes an output count that is a floor, not an exact value.
28		partialMark = "≥ "
29		// stem and lastStem draw the tree branch in front of a sub-agent's type.
30		stem     = "├─ "
31		lastStem = "└─ "
32	)
33	
34	// agentIDPrefix is the shortest agent ID shown.
35	const agentIDPrefix = 8
36	
37	// agentRow is one line of the agents table.
38	type agentRow struct {
39		agentusage.Agent
40		branch  string // stem, lastStem, or "" (orchestrator, or a sorted list)
41		shortID string // ID prefix, distinct within the session; "" for the orchestrator
42		share   int    // tenths of a percent of the session total, or noShare
43	}
44	
45	// agentRows orders a session's agents (orchestrator, then sub-agents by ID),
46	// gives each its short ID and share, and draws the branches when tree is true.
47	// The sort is stable so equal IDs keep their input order.
48	func agentRows(u agentusage.Usage, tree bool) []agentRow {
49		var main, subs []agentusage.Agent
50		for _, a := range u.Agents {
51			if a.Main {
52				main = append(main, a)
53			} else {
54				subs = append(subs, a)
55			}
56		}
57		sort.SliceStable(subs, func(i, j int) bool { return subs[i].ID < subs[j].ID })
58	
59		ordered := append(append([]agentusage.Agent{}, main...), subs...)
60		totals := make([]int64, len(ordered))
61		for i, a := range ordered {
62			totals[i] = a.Tokens.Total()
63		}
64		mainIdx := -1
65		if len(main) > 0 {
66			mainIdx = 0
67		}
68		parts := shares(totals, u.Total().Total(), mainIdx)
69	
70		ids := make([]string, len(subs))
71		for i, a := range subs {
72			ids[i] = a.ID
73		}
74		short := shortAgentIDs(ids)
75	
76		rows := make([]agentRow, 0, len(ordered))
77		for i, a := range ordered {
78			row := agentRow{Agent: a, share: parts[i]}
79			if !a.Main {
80				j := i - len(main)
81				row.shortID = short[j]
82				if tree {
83					row.branch = stem
84					if j == len(subs)-1 {
85						row.branch = lastStem
86					}
87				}
88			}
89			rows = append(rows, row)
90		}
91		return rows
92	}
93	
94	// shortAgentIDs cuts every ID to one common length, the smallest n >=
95	// agentIDPrefix (in runes) at which all of them differ, capped at each ID's
96	// own length.
97	func shortAgentIDs(ids []string) []string {
98		if len(ids) == 0 {
99			return nil
100		}
101		longest := 0
102		runes := make([][]rune, len(ids))
103		for i, id := range ids {
104			runes[i] = []rune(id)
105			longest = max(longest, len(runes[i]))
106		}
107		cut := func(n int) []string {
108			out := make([]string, len(runes))
109			for i, r := range runes {
110				out[i] = string(r[:min(n, len(r))])
111			}
112			return out
113		}
114		for n := agentIDPrefix; n < longest; n++ {
115			seen := make(map[string]bool, len(ids))
116			distinct := true
117			for _, s := range cut(n) {
118				if seen[s] {
119					distinct = false
120					break
121				}
122				seen[s] = true
123			}
124			if distinct {
125				return cut(n)
126			}
127		}
128		return cut(longest)
129	}
130	
131	// agentColumns describes the agents table. Only Total sorts, largest first;
132	// without a sort the order is the tree. Columns give way on a narrow terminal
133	// in this order: Cache write, Cache read, In, Model. The ID never does, so two
134	// agents of one type stay apart.
135	func agentColumns() []datatable.Column[agentRow] {
136		count := func(title string, width int, tokens func(agentRow) int64) datatable.Column[agentRow] {
137			return datatable.Column[agentRow]{
138				Title: title, Sizing: datatable.SizingFixed, MinWidth: width,
139				Cell:  func(r agentRow) string { return formatTokens(tokens(r)) },
140				Style: func(r agentRow) lipgloss.Style { return dimWhen(tokens(r) == 0) },
141			}
142		}
143		in := count("In", 6, func(r agentRow) int64 { return r.Tokens.Input })
144		in.Optional = true
145		cacheRead := count("Cache read", len("Cache read"), func(r agentRow) int64 { return r.Tokens.CacheRead })
146		cacheRead.Optional = true
147		cacheWrite := count("Cache write", len("Cache write"), func(r agentRow) int64 { return r.Tokens.CacheWrite })
148		cacheWrite.Optional, cacheWrite.DropFirst = true, true
149		total := count("Total", 6, func(r agentRow) int64 { return r.Tokens.Total() })
150		total.Less = func(a, b agentRow) bool { return a.Tokens.Total() < b.Tokens.Total() }
151		total.DescFirst = true
152	
153		out := count("Out", 7, nil)
154		out.Cell = outCell
155		out.Style = func(r agentRow) lipgloss.Style { return dimWhen(r.Tokens.Output == 0) }
156	
157		return []datatable.Column[agentRow]{
158			{Title: "Agent", Sizing: datatable.SizingContent, MinWidth: 14, Cell: roleCell, Search: agentSearch,
159				Style: func(r agentRow) lipgloss.Style { return dimWhen(!r.Main && r.Type == "") }},
160			{Title: "ID", Sizing: datatable.SizingContent, MinWidth: agentIDPrefix, Cell: idCell,
161				Search: func(r agentRow) string { return r.ID },
162				Style:  func(r agentRow) lipgloss.Style { return dimWhen(idCell(r) == noValue || idCell(r) == unknownID) }},
163			{Title: "Model", Sizing: datatable.SizingContent, MinWidth: 12, Flex: 2, Optional: true, Cell: modelsCell, Search: modelsCell,
164				Style: func(r agentRow) lipgloss.Style { return dimWhen(len(r.Models) == 0) }},
165			in, out, cacheRead, cacheWrite, total,
166			{Title: "Share", Sizing: datatable.SizingFixed, MinWidth: len("100.0%"), Cell: shareCell,
167				Style: func(r agentRow) lipgloss.Style { return dimWhen(r.share <= 0) }},
168		}
169	}
170	
171	// dimWhen is Rule 122's colour discipline: a zero or a placeholder is dim,
172	// anything else keeps the default colour.
173	func dimWhen(dim bool) lipgloss.Style {
174		if dim {
175			return theme.DimStyle
176		}
177		return lipgloss.NewStyle()
178	}
179	
180	// agentSearch is what `/` matches in the Agent column: the role. The full ID is
181	// searched through the ID column.
182	func agentSearch(r agentRow) string { return roleCell(r) }
183	
184	// idCell is the ID column: the short ID of a sub-agent, a dash for the
185	// orchestrator, which has none.
186	func idCell(r agentRow) string {
187		switch {
188		case r.Main:
189			return noValue
190		case r.shortID == "":
191			return unknownID
192		}
193		return r.shortID
194	}
195	
196	// shareCell is the Share column.
197	func shareCell(r agentRow) string { return formatShare(r.share) }
198	
199	// roleCell is the Agent cell: "orchestrator", or the sub-agent's type behind
200	// its branch.
201	func roleCell(r agentRow) string {
202		if r.Main {
203			return orchestratorLabel
204		}
205		typ := r.Type
206		if typ == "" {
207			typ = unknownType
208		}
209		return r.branch + typ
210	}
211	
212	// modelsCell lists the models the agent used.
213	func modelsCell(r agentRow) string {
214		if len(r.Models) == 0 {
215			return noModel
216		}
217		return strings.Join(r.Models, ", ")
218	}
219	
220	// outCell is the output count. A sub-agent still being written is a floor and
221	// says so; the orchestrator never does, its transcript is the one being read.
222	func outCell(r agentRow) string {
223		out := formatTokens(r.Tokens.Output)
224		if !r.Main && r.PartialOutput() {
225			return partialMark + out
226		}
227		return out
228	}
229	
230	// formatTokens renders a count compactly, floored to one decimal: 1099 is
231	// "1.0k", never "1.1k". From 100 of a unit up the decimal is dropped.
232	func formatTokens(n int64) string {
233		units := []struct {
234			size   int64
235			suffix string
236		}{
237			{1_000_000_000_000, "T"}, {1_000_000_000, "B"}, {1_000_000, "M"}, {1_000, "k"},
238		}
239		for _, u := range units {
240			if n < u.size {
241				continue
242			}
243			tenths := n / (u.size / 10) // divide first: n*10 would overflow
244			if tenths >= 1000 {
245				return fmt.Sprintf("%d%s", tenths/10, u.suffix)
246			}
247			return fmt.Sprintf("%d.%d%s", tenths/10, tenths%10, u.suffix)
248		}
249		return fmt.Sprintf("%d", n)
250	}
251

