290	// String shows counts only: an Aggregate holds paths, and the value receiver
291	// also covers a dereferenced *a.
292	func (a Aggregate) String() string {
293		return fmt.Sprintf("agentusage.Aggregate{files: %d, applied: %d}", len(a.files), a.seq)
294	}
295	
296	// GoString shows counts only.
297	func (a Aggregate) GoString() string { return a.String() }
298	
299	// NewAggregate starts an empty aggregate for the session whose parent
300	// transcript is parentTranscript (<dir>/<uuid>.jsonl). It does no I/O.
301	func NewAggregate(parentTranscript string) *Aggregate {
302		base := filepath.Base(parentTranscript)
303		return &Aggregate{
304			parent:    parentTranscript,
305			id:        aggregateIDs.Add(1),
306			fresh:     true,
307			sessionID: sanitizeLabel(strings.TrimSuffix(base, transcriptExt)),
308			files:     []fileCursor{newFileCursor(parentTranscript, sanitizeLabel(base), "", parentRank)},
309			t:         newTable(),
310		}
311	}
312	
313	// Cursor returns a copy of the aggregate's position, to hand to ReadDelta.
314	func (a *Aggregate) Cursor() Cursor {
315		return Cursor{
316			parent: a.parent, id: a.id, seq: a.seq, fresh: a.fresh,
317			files: slices.Clone(a.files), metas: slices.Clone(a.metas),
318		}
319	}
320	
321	// Apply folds d in, or replaces everything with it when d.Full(). It returns
322	// ErrStaleDelta, and changes nothing, if d was not read from a.Cursor(). It
323	// takes ownership of d.
324	func (a *Aggregate) Apply(d Delta) error {
325		if !d.valid || d.id != a.id || d.seq != a.seq {
326			return ErrStaleDelta
327		}
328		switch {
329		case d.full:
