package containers

import (
	"time"

	tea "github.com/charmbracelet/bubbletea"

	"github.com/anthnel/devdesk/internal/docker"
)

// refreshInterval is the cadence of the view's reload. A variable so a test can
// shorten it: tea.Tick sleeps for the whole duration.
var refreshInterval = 2 * time.Second

// tickCmd returns the next tick of the periodic refresh. It is a single shot:
// each RefreshTickMsg asks for the one after it, and the chain ends by itself
// when the view stops being the active one, because the router then hands the
// tick to the view on screen, which ignores it. Init starts a new chain on the
// way back in.
func tickCmd() tea.Cmd {
	return tea.Tick(refreshInterval, func(t time.Time) tea.Msg {
		return RefreshTickMsg(t)
	})
}

// fetchContainers fetches the container list — always all of it.
//
// The scope used to be docker's: `a` flipped `--all` and refetched, so the rows
// the user could not see did not exist locally either. The state filter is the
// table's now, and a filter can only narrow what it holds, so the list has to
// arrive whole. It also means toggling a state is instant rather than a round
// trip to the daemon.
func fetchContainers() tea.Cmd {
	return func() tea.Msg {
		containers, err := docker.ListContainers(true)
		return ContainersListMsg{Containers: containers, Err: err}
	}
}

// fetchMetrics fetches container metrics

