72	func batchMsgs(t *testing.T, cmd tea.Cmd) []tea.Msg {
73		t.Helper()
74		if cmd == nil {
75			return nil
76		}
77		cmds := []tea.Cmd{cmd}
78		if b, ok := cmd().(tea.BatchMsg); ok {
79			cmds = b
80		}
81		out := make(chan tea.Msg, len(cmds))
82		for _, c := range cmds {
83			go func() {
